# frozen_string_literal: true

# A simple fixed-capacity LRU cache.
#
# Relies on Ruby's insertion-ordered Hash: the first key is always the
# least recently used, and touching a key moves it to the end.
class LRUCache
  attr_reader :capacity

  def initialize(capacity)
    raise ArgumentError, "capacity must be a positive Integer" unless capacity.is_a?(Integer) && capacity.positive?

    @capacity = capacity
    @store = {}
  end

  # Returns the value for key (or nil), marking it as most recently used.
  def get(key)
    return nil unless @store.key?(key)

    value = @store.delete(key)
    @store[key] = value
  end
  alias [] get

  # Stores value under key, evicting the least recently used entry if full.
  def set(key, value)
    @store.delete(key)
    @store[key] = value
    @store.delete(@store.first[0]) if @store.size > @capacity
    value
  end
  alias []= set

  def delete(key)
    @store.delete(key)
  end

  def key?(key)
    @store.key?(key)
  end

  def size
    @store.size
  end

  def clear
    @store.clear
    self
  end

  # Keys ordered from least to most recently used.
  def keys
    @store.keys
  end
end
